package memory

import (
	"context"
	"fmt"
	"sync"
	"time"

	graphragffi "knirv-server/pkg/embedded/graphrag"
)

type GraphRAGInterface interface {
	Query(ctx context.Context, kbID string, query *GraphRAGQuery) (*GraphRAGResult, error)
	BuildIndex(ctx context.Context, kbID string, strategy string) (*IndexStatus, error)
	GetIndexStatus(ctx context.Context, kbID string) (*IndexStatus, error)
	Close() error
}

type GraphRAGQuery struct {
	Query  string                 `json:"query"`
	Mode   string                 `json:"mode"`
	Limit  int                    `json:"limit"`
	Params map[string]interface{} `json:"params"`
}

type GraphRAGResult struct {
	ID        string      `json:"id"`
	Query     string      `json:"query"`
	Mode      string      `json:"mode"`
	Nodes     []GraphNode `json:"nodes"`
	Edges     []GraphEdge `json:"edges"`
	Chunks    []TextChunk `json:"chunks"`
	Summary   string      `json:"summary"`
	Score     float64     `json:"score"`
	Timestamp time.Time   `json:"timestamp"`
}

type GraphRAGClient struct {
	ffi     *graphragffi.Client
	indexes map[string]*GraphRAGIndex
	mu      sync.RWMutex
	running bool
}

type GraphRAGIndex struct {
	KBID        string
	RustHandle  interface{}
	Status      string
	NodesCount  int
	EdgesCount  int
	ChunksCount int
	LastUpdated time.Time
}

func NewGraphRAGClient() *GraphRAGClient {
	return &GraphRAGClient{
		ffi:     graphragffi.NewClient(nil),
		indexes: make(map[string]*GraphRAGIndex),
		running: true,
	}
}

func (c *GraphRAGClient) Query(ctx context.Context, kbID string, query *GraphRAGQuery) (*GraphRAGResult, error) {
	c.mu.RLock()
	index, ok := c.indexes[kbID]
	c.mu.RUnlock()

	if !ok {
		return nil, fmt.Errorf("index not found for knowledge base: %s", kbID)
	}

	if index.Status != "ready" {
		return nil, fmt.Errorf("index is not ready (status: %s)", index.Status)
	}

	ffiQuery := &graphragffi.GraphQuery{
		Query:  query.Query,
		Mode:   query.Mode,
		Limit:  query.Limit,
		Params: query.Params,
	}

	ffiResult, err := c.ffi.Query(ctx, kbID, ffiQuery)
	if err != nil {
		return nil, fmt.Errorf("graphrag query failed: %w", err)
	}

	nodes := make([]GraphNode, len(ffiResult.Nodes))
	for i, n := range ffiResult.Nodes {
		nodes[i] = GraphNode{
			ID:    n.ID,
			Type:  n.Type,
			Data:  n.Data,
			Score: n.Score,
		}
	}

	edges := make([]GraphEdge, len(ffiResult.Edges))
	for i, e := range ffiResult.Edges {
		edges[i] = GraphEdge{
			Source:     e.Source,
			Target:     e.Target,
			Type:       e.Type,
			Weight:     e.Weight,
			Attributes: e.Attributes,
		}
	}

	chunks := make([]TextChunk, len(ffiResult.Chunks))
	for i, c := range ffiResult.Chunks {
		chunks[i] = TextChunk{
			ID:        c.ID,
			Content:   c.Content,
			Relevance: c.Relevance,
			Source:    c.Source,
		}
	}

	result := &GraphRAGResult{
		ID:        ffiResult.ID,
		Query:     ffiResult.Query,
		Mode:      ffiResult.Mode,
		Nodes:     nodes,
		Edges:     edges,
		Chunks:    chunks,
		Summary:   ffiResult.Summary,
		Score:     ffiResult.Score,
		Timestamp: ffiResult.Timestamp,
	}

	return result, nil
}

func (c *GraphRAGClient) BuildIndex(ctx context.Context, kbID string, strategy string) (*IndexStatus, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	status := &IndexStatus{
		KBID:        kbID,
		Status:      "building",
		Progress:    0,
		NodesCount:  0,
		EdgesCount:  0,
		ChunksCount: 0,
		LastUpdated: time.Now(),
	}

	go func() {
		ffiStatus, err := c.ffi.BuildIndex(ctx, kbID, strategy)
		if err != nil {
			c.mu.Lock()
			c.indexes[kbID] = &GraphRAGIndex{
				KBID:   kbID,
				Status: "error",
			}
			c.mu.Unlock()
			return
		}

		c.mu.Lock()
		defer c.mu.Unlock()

		idx := &GraphRAGIndex{
			KBID:        kbID,
			Status:      ffiStatus.Status,
			NodesCount:  ffiStatus.NodesCount,
			EdgesCount:  ffiStatus.EdgesCount,
			ChunksCount: ffiStatus.ChunksCount,
			LastUpdated: time.Now(),
		}

		c.indexes[kbID] = idx
	}()

	return status, nil
}

func (c *GraphRAGClient) GetIndexStatus(ctx context.Context, kbID string) (*IndexStatus, error) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	index, ok := c.indexes[kbID]
	if !ok {
		return &IndexStatus{
			KBID:   kbID,
			Status: "not_built",
		}, nil
	}

	return &IndexStatus{
		KBID:        index.KBID,
		Status:      index.Status,
		Progress:    100.0,
		NodesCount:  index.NodesCount,
		EdgesCount:  index.EdgesCount,
		ChunksCount: index.ChunksCount,
		LastUpdated: index.LastUpdated,
	}, nil
}

func (c *GraphRAGClient) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()

	c.running = false
	c.indexes = make(map[string]*GraphRAGIndex)

	return c.ffi.Close()
}

